import React, { useState } from 'react'
import Button from '../Button/Button'
import Card from '../Card/Card'
import { Backdrops } from '../Dialog/Dialog'
import {
  Add,
  Alarm,
  CheckCircleOutline,
  Delete,
  Domain,
  Edit,
  PanelClose,
  Search,
  SupportAgent,
} from '../icons'
import Progress from '../Progress/Progress'
import Select from '../Select/Select'
import Typography from '../Typography/Typography'
import type { DrawerProps } from './Drawer'
import Drawer from './Drawer'

const backdrops = {
  Default: undefined,
  'Backdrops.Dark': Backdrops.Dark,
  'Backdrops.Light': Backdrops.Light,
}

export default {
  title: 'Components/Drawer',
  component: Drawer,
  argTypes: {
    ariaLabel: {
      control: { type: 'text' },
    },
    backdrop: {
      control: { type: 'select' },
      options: Object.keys(backdrops),
      mapping: backdrops,
    },
    placement: {
      control: { type: 'select' },
      options: ['left', 'right', 'top', 'bottom'],
    },
    dismissable: {
      control: { type: 'boolean' },
    },
    panelOffset: {
      control: { type: 'object' },
    },
    open: {
      control: false,
    },
    onOpenChange: {
      control: { type: 'object' },
    },
  },
  args: {
    backdrop: 'Backdrops.Dark',
    placement: 'right',
    dismissable: true,
    open: false,
  },
}

function Template(args: DrawerProps): JSX.Element {
  const [open, setOpen] = useState(false)

  return (
    <>
      <Button onClick={() => setOpen(true)} variant="outlined">
        Open Drawer
      </Button>
      <Drawer {...args} onOpenChange={setOpen} open={open}>
        <Drawer.Header>
          <Typography variant="h5">Drawer Title</Typography>
        </Drawer.Header>
        <div className="flex flex-col p-6 gap-4">
          <Typography variant="body2">
            This is the drawer content. You can place any content here. Click
            outside or press Escape to close.
          </Typography>
          <Button onClick={() => setOpen(false)} variant="outlined">
            Close Drawer
          </Button>
        </div>
      </Drawer>
    </>
  )
}

export const Default = {
  render: Template,
}

export function AllPlacements(): JSX.Element {
  const [placement, setPlacement] = useState<DrawerProps['placement']>('right')
  const [open, setOpen] = useState(false)

  const handleOpen = (p: DrawerProps['placement']) => {
    setPlacement(p)
    setOpen(true)
  }

  return (
    <>
      <div className="flex justify-center items-center gap-3">
        <Button onClick={() => handleOpen('left')} variant="outlined">
          Left
        </Button>
        <Button onClick={() => handleOpen('right')} variant="outlined">
          Right
        </Button>
        <Button onClick={() => handleOpen('top')} variant="outlined">
          Top
        </Button>
        <Button onClick={() => handleOpen('bottom')} variant="outlined">
          Bottom
        </Button>
      </div>
      <Drawer onOpenChange={setOpen} open={open} placement={placement}>
        <Drawer.Header>
          <Typography variant="h5">
            {' '}
            {placement
              ? placement.charAt(0).toUpperCase() + placement.slice(1)
              : ''}{' '}
          </Typography>
        </Drawer.Header>
        <div className="p-6">
          <Typography variant="body2">
            Slides in from the {placement} edge of the screen.
          </Typography>
        </div>
      </Drawer>
    </>
  )
}

export function LightBackdrop(): JSX.Element {
  const [open, setOpen] = useState(false)

  return (
    <>
      <Button onClick={() => setOpen(true)} variant="outlined">
        Open Drawer
      </Button>
      <Drawer backdrop={Backdrops.Light} onOpenChange={setOpen} open={open}>
        <Drawer.Header>
          <Typography variant="h5">Light Backdrop</Typography>
        </Drawer.Header>
        <div className="p-6">
          <Typography variant="body2">
            This drawer uses a white overlay behind the panel.
          </Typography>
        </div>
      </Drawer>
    </>
  )
}

export function NonDismissable(): JSX.Element {
  const [open, setOpen] = useState(false)

  return (
    <>
      <Button onClick={() => setOpen(true)} variant="outlined">
        Open Drawer
      </Button>
      <Drawer dismissable={false} onOpenChange={setOpen} open={open}>
        <Drawer.Header>
          <Typography variant="h5">Non dismissable</Typography>
        </Drawer.Header>
        <div className="p-6">
          <Typography variant="body2">
            This drawer cannot be dismissed by clicking outside or pressing
            Escape. No dismiss button is rendered in the header. Use the button
            below to close it.
          </Typography>
          <div className="mt-8 flex justify-end">
            <Button
              color="secondary"
              endAdornment={CheckCircleOutline}
              fullWidth
              onClick={() => setOpen(false)}
              variant="outlined"
            >
              Close programmatically
            </Button>
          </div>
        </div>
      </Drawer>
    </>
  )
}

export function RichContent(): JSX.Element {
  const [open, setOpen] = useState(false)

  return (
    <>
      <Button
        endAdornment={Edit}
        onClick={() => setOpen(true)}
        variant="outlined"
      >
        Edit Outcomes
      </Button>

      <Drawer
        ariaLabelledBy="edit-outcomes-title"
        onOpenChange={setOpen}
        open={open}
      >
        <Drawer.Header>
          <div className="flex gap-4 items-center">
            <Typography id="edit-outcomes-title" variant="h5">
              Edit Outcomes
            </Typography>
            <Progress color="primary" size="small" variant="circular" />
            <Typography variant="caption">Thinking...</Typography>
          </div>
        </Drawer.Header>
        <div className="p-6 flex flex-col gap-6">
          <div className="p-4 bg-primary-10 rounded">
            <div className="flex items-center justify-start gap-2">
              <div className="w-6 h-6">
                <SupportAgent />
              </div>
              <p>Pizza delivery</p>
            </div>
            <p style={{ color: 'slategrey' }}>For a Tanka Jahari</p>
          </div>
          {['1', '2', '3', '4', '5', '6'].map((n) => {
            return (
              <Card key={n} outlined>
                <Card.Header>
                  <Card.Title>{`Meeting Outcome #${n}`}</Card.Title>
                </Card.Header>
                <Card.Content>
                  <div className="flex flex-col">
                    <Select
                      defaultValue={n}
                      helperText="Tracking outcomes is good!"
                      label="Outcome Category"
                      variant="filled"
                    >
                      <Select.Option value="1">Applied lipstick</Select.Option>
                      <Select.Option value="2">
                        Pizza thrown on the ground
                      </Select.Option>
                    </Select>
                  </div>
                  <div className="flex justify-end">
                    <Button startAdornment={Delete} variant="outlined">
                      Remove
                    </Button>
                  </div>
                </Card.Content>
              </Card>
            )
          })}
          <Button startAdornment={Add} variant="contained">
            Add Outcome
          </Button>
        </div>
      </Drawer>
    </>
  )
}

export function PanelOffset(): JSX.Element {
  const [open, setOpen] = useState(false)

  return (
    <div className="relative min-h-screen">
      <div className="fixed top-0 left-0 right-0 h-16 bg-green-400 flex items-center justify-between px-4 z-50 shadow-3">
        <div className="flex items-center gap-3 text-black-100">
          <div className="w-6 h-6">
            <Domain />
          </div>
        </div>
        <div className="flex items-center gap-2 text-black-100">
          <div className="w-5 h-5">
            <Search />
          </div>
          <div className="w-5 h-5">
            <Alarm />
          </div>
          <Button
            endAdornment={PanelClose}
            onClick={() => setOpen(true)}
            variant="outlined"
          >
            Open
          </Button>
        </div>
      </div>
      <div className="pt-20 px-6">
        <Typography variant="h5">Dashboard</Typography>
      </div>
      <Drawer
        backdropBlurred={false}
        onOpenChange={setOpen}
        open={open}
        panelOffset={{ top: '64px' }}
        placement="right"
      >
        <Drawer.Header>
          <Typography variant="h5">Panel Offset</Typography>
        </Drawer.Header>
        <div className="p-6">
          <Typography variant="body2">
            This drawer has an offset of 64px from the top edge of the screen,
            allowing the user to still see the header. The ModalOverlay
            component behind the drawer still covers the entire screen.
          </Typography>
        </div>
      </Drawer>
    </div>
  )
}
